"""Deterministic command router. These placeholders do not call an AI model."""

def route(command: str, text: str) -> dict:
    if not isinstance(command, str) or not isinstance(text, str):
        raise TypeError('command and text must be strings')
    command, text = command.strip().lower(), text.strip()
    if not text:
        raise ValueError('text must not be empty')
    handlers = {
        'research': lambda value: {'query': value, 'status': 'not_searched'},
        'summarize': lambda value: {'preview': value[:40], 'status': 'not_summarized'},
        'extract': lambda value: {'words': value.split(), 'status': 'local_split'},
    }
    if command not in handlers:
        raise ValueError('unknown command')
    return {'action': command, 'result': handlers[command](text)}


if __name__ == '__main__':
    print(route('extract', 'hello agent builders'))

"""Validated conversation persistence. Corrupt input is never silently erased."""
import json
import os
from pathlib import Path
from tempfile import NamedTemporaryFile


def validate(messages: object) -> list:
    if not isinstance(messages, list):
        raise ValueError('conversation must be a list')
    for message in messages:
        if not isinstance(message, dict):
            raise ValueError('message must be an object')
        if message.get('role') not in ('user', 'assistant'):
            raise ValueError('unsupported role')
        if not isinstance(message.get('content'), str):
            raise ValueError('content must be a string')
    return messages


def load_messages(path: Path) -> list:
    try:
        content = path.read_text(encoding='utf-8')
    except FileNotFoundError:
        return []
    return validate(json.loads(content))


def save_messages(path: Path, messages: list) -> None:
    validate(messages)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with NamedTemporaryFile(mode='w', encoding='utf-8', dir=path.parent,
                                delete=False) as handle:
            temporary = Path(handle.name)
            json.dump(messages, handle, ensure_ascii=False, indent=2)
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


if __name__ == '__main__':
    from tempfile import TemporaryDirectory
    with TemporaryDirectory() as directory:
        path = Path(directory) / 'conversation.json'
        save_messages(path, [{'role': 'user', 'content': 'שלום'}])
        print(load_messages(path))

"""A local HTTP lab: two endpoints, rate limit, bad JSON and a missing route."""
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from threading import Thread
from urllib.request import urlopen


class LabHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        routes = {'/customer': {'id': 'C1', 'name': 'Demo customer'},
                  '/product': {'id': 'P1', 'name': 'Demo product'}}
        if self.path in routes:
            status, body = 200, json.dumps(routes[self.path]).encode()
        elif self.path == '/limited':
            status, body = 429, b'{"error":"rate_limited"}'
        elif self.path == '/invalid':
            status, body = 200, b'not-json'
        else:
            status, body = 404, b'{"error":"not_found"}'
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        if status == 429:
            self.send_header('Retry-After', '1')
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *args):
        pass


def fetch(base: str, endpoint: str) -> dict:
    with urlopen(base + endpoint, timeout=2) as response:
        data = json.loads(response.read().decode('utf-8'))
    if not isinstance(data, dict):
        raise ValueError('expected JSON object')
    return {'source': endpoint, 'data': data}


if __name__ == '__main__':
    server = ThreadingHTTPServer(('127.0.0.1', 0), LabHandler)
    worker = Thread(target=server.serve_forever, daemon=True)
    worker.start()
    try:
        base = f'http://127.0.0.1:{server.server_port}'
        print(fetch(base, '/customer'))
        print(fetch(base, '/product'))
    finally:
        server.shutdown()
        server.server_close()
        worker.join()

"""Provider-independent control loop. The scripted model is explicitly a test double."""
import json


def lookup_customer(customer_id: str) -> dict:
    if not isinstance(customer_id, str):
        raise ValueError('customer_id must be text')
    customers = {'C1': {'name': 'Demo customer', 'status': 'active'}}
    if customer_id not in customers:
        raise ValueError('customer not found')
    return customers[customer_id]


def run_agent(model, goal: str, max_steps: int = 4) -> dict:
    if not isinstance(max_steps, int) or isinstance(max_steps, bool) or not 1 <= max_steps <= 20:
        raise ValueError('max_steps must be 1..20')
    history = [{'role': 'user', 'content': goal}]
    tools = {'lookup_customer': lookup_customer}
    for step in range(max_steps):
        decision = model(list(history))
        if not isinstance(decision, dict):
            raise ValueError('model response must be an object')
        if decision.get('kind') == 'final':
            if not isinstance(decision.get('text'), str):
                raise ValueError('final text must be a string')
            return {'status': 'completed', 'result': decision['text'], 'trace': history}
        if decision.get('kind') != 'tool' or decision.get('name') not in tools:
            raise ValueError('unknown tool decision')
        arguments = decision.get('arguments')
        if not isinstance(arguments, dict) or set(arguments) != {'customer_id'}:
            raise ValueError('invalid tool arguments')
        try:
            result = tools[decision['name']](arguments['customer_id'])
            observation = {'ok': True, 'data': result}
        except ValueError as error:
            observation = {'ok': False, 'error': str(error)}
        history.append({'role': 'tool', 'step': step,
                        'name': decision['name'], 'content': json.dumps(observation)})
    return {'status': 'step_limit', 'result': None, 'trace': history}


def scripted_model(history):
    if len(history) == 1:
        return {'kind': 'tool', 'name': 'lookup_customer',
                'arguments': {'customer_id': 'C1'}}
    return {'kind': 'final', 'text': 'Demo: lookup finished; inspect the tool observation.'}


if __name__ == '__main__':
    print(json.dumps(run_agent(scripted_model, 'Look up customer C1'), indent=2))

'use client';
import { useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { reducedMotion } from '@/lib/domain/motion';
import { Sparkles } from 'lucide-react';
const greetings = [
  'היי, אני Byte! נבנה משהו קטן ונגלה איך הוא עובד.',
  'נתקעת? שנה דבר אחד בכל פעם והשווה בין התוצאות.',
  'משימה גדולה? חלק אותה לשלושה צעדים ובדוק קודם את הצעד הראשון.',
];

/** Drop a lazy Spline/WebGL scene into `scene`; the CSS character remains the no-network fallback. */
export function AiMascot({
  compact = false,
  mood = 'curious',
  scene,
}: {
  compact?: boolean;
  mood?: 'curious' | 'happy';
  scene?: ReactNode;
}) {
  const rig = useRef<HTMLDivElement>(null);
  const [waving, setWaving] = useState(false);
  const [greeting, setGreeting] = useState(-1);
  function greet() {
    setWaving(true);
    setGreeting((value) => (value + 1) % greetings.length);
  }
  function track(event: React.PointerEvent<HTMLDivElement>) {
    if (event.pointerType === 'touch' || reducedMotion()) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const x = (event.clientX - rect.left) / rect.width - 0.5,
      y = (event.clientY - rect.top) / rect.height - 0.5;
    rig.current?.style.setProperty('--look-x', `${x * 15}px`);
    rig.current?.style.setProperty('--look-y', `${y * 10}px`);
  }
  function reset() {
    rig.current?.style.setProperty('--look-x', '0px');
    rig.current?.style.setProperty('--look-y', '0px');
  }
  return (
    <div
      className={`mascot-stage ${compact ? 'compact' : ''} ${waving || mood === 'happy' ? 'is-happy' : ''}`}
      onPointerMove={track}
      onPointerLeave={reset}
      data-spline-slot="ai-companion"
    >
      <div className="mascot-grid" aria-hidden="true" />
      <div className="orbital orbital-one" aria-hidden="true" />
      <div className="orbital orbital-two" aria-hidden="true" />
      <div className="floating-symbol symbol-one" aria-hidden="true">
        {'{ }'}
      </div>
      <div className="floating-symbol symbol-two" aria-hidden="true">
        ✦
      </div>
      <div className="floating-symbol symbol-three" aria-hidden="true">
        ⌘
      </div>
      {scene ?? (
        <div
          ref={rig}
          className="mascot-rig"
          aria-hidden="true"
          style={{ '--look-x': '0px', '--look-y': '0px' } as CSSProperties}
        >
          <div className="bot-antenna">
            <i />
          </div>
          <div className="bot-shell">
            <div className="bot-highlight" />
            <div className="bot-face">
              <div className="bot-eyes">
                <i />
                <i />
              </div>
              <div className="bot-smile" />
            </div>
            <div className="bot-ear ear-left" />
            <div className="bot-ear ear-right" />
          </div>
          <div className="bot-body">
            <i />
            <i />
            <i />
          </div>
          <div className="bot-hand hand-left" />
          <div className="bot-hand hand-right" />
        </div>
      )}
      <div className="mascot-shadow" aria-hidden="true" />
      <button
        type="button"
        className="mascot-touch-target"
        aria-label="הצגת הודעה מ־Byte"
        onClick={greet}
      />
      {greeting >= 0 && (
        <div className="mascot-speech" key={greeting} role="status">
          <p>{greetings[greeting]}</p>
          <button
            type="button"
            className="icon-button"
            aria-label="סגירת הודעת Byte"
            onClick={() => {
              setGreeting(-1);
              setWaving(false);
            }}
          >
            ×
          </button>
        </div>
      )}
      <button
        type="button"
        className="mascot-greeting"
        onClick={greet}
        aria-expanded={greeting >= 0}
      >
        <Sparkles size={14} />
        {waving ? 'היי! מוכן לבנות?' : 'תגיד לי שלום'}
      </button>
      {!compact && (
        <span className="mascot-caption" dir="ltr">
          <i /> BYTE · YOUR ARCADE SIDEKICK
        </span>
      )}
    </div>
  );
}

'use client';
import { useState, type CSSProperties } from 'react';
import Link from 'next/link';
import { Check, LockKeyhole, Play, ArrowLeft, Map, Clock3 } from 'lucide-react';
import type { Lesson, Curriculum } from '@/lib/curriculum/schema';
import type { Progress } from '@/lib/domain/progress';

export function LessonMap({
  lessons,
  weeks,
  records,
  lockedIds,
}: {
  lessons: Lesson[];
  weeks: Curriculum['weeks'];
  records: Progress[];
  lockedIds: string[];
}) {
  const [week, setWeek] = useState(1),
    [selectedId, setSelectedId] = useState(lessons[0].id);
  const visible = lessons.filter((lesson) => lesson.week === week),
    selected = visible.find((l) => l.id === selectedId) ?? visible[0];
  const built = new Set(
    records.filter((record) => record.buildCompletedAt).map((record) => record.lessonId),
  );
  return (
    <section className="lesson-map card" aria-labelledby="map-title">
      <div className="map-heading">
        <div>
          <p className="eyebrow">SELECT YOUR LEVEL</p>
          <h2 id="map-title">
            <Map size={20} /> מפת המסע שלך
          </h2>
        </div>
        <label className="week-selector">
          <span className="sr-only">בחירת שבוע במפה</span>
          <select value={week} onChange={(event) => setWeek(Number(event.target.value))}>
            {weeks.map((w) => (
              <option key={w.id} value={w.number}>
                שבוע {w.number} · {w.title}
              </option>
            ))}
          </select>
        </label>
      </div>
      <div className="map-foundation-banner">
        <span className="pill">
          {week === 1 ? 'מתחילים כאן · שבוע 1' : 'קודם בונים את היסודות'}
        </span>
        <p>פרק היסודות הוא נקודת ההתחלה. מסיימים את תרגילי החובה לפני שפותחים התמחות חדשה.</p>
        <Link href="/topics/CORE" className="text-link">
          לפרק היסודות ולסדר הלמידה ←
        </Link>
      </div>
      <div className="map-legend">
        <span>
          <i className="legend-built" /> הבנייה הושלמה
        </span>
        <span>
          <i className="legend-active" /> זמין ללמידה
        </span>
        <span>
          <i className="legend-locked" /> אחרי פרק היסודות
        </span>
      </div>
      <div className="node-path" dir="ltr">
        <svg viewBox="0 0 500 170" preserveAspectRatio="none" aria-hidden="true">
          <path d="M50 55 H100 V110 H200 V55 H300 V110 H400 V55 H450" />
        </svg>
        {visible.map((lesson, i) => {
          const state = lockedIds.includes(lesson.id)
            ? 'locked'
            : built.has(lesson.id)
              ? 'built'
              : lesson.publicationStatus === 'published'
                ? 'active'
                : 'locked';
          return (
            <button
              key={lesson.id}
              className={`map-node ${state} ${selected.id === lesson.id ? 'selected' : ''}`}
              style={
                {
                  '--node-x': `${10 + i * 20}%`,
                  '--node-y': `${i % 2 ? 110 : 55}px`,
                } as CSSProperties
              }
              onClick={() => setSelectedId(lesson.id)}
              aria-pressed={selected.id === lesson.id}
              aria-label={`יום ${lesson.day}: ${lesson.title} · ${state === 'built' ? 'הבנייה הושלמה' : state === 'active' ? 'זמין' : 'נעול עד להשלמת פרק היסודות'}`}
            >
              <span className="node-ring">
                {state === 'built' ? (
                  <Check size={21} />
                ) : state === 'active' ? (
                  <Play size={19} fill="currentColor" />
                ) : (
                  <LockKeyhole size={17} />
                )}
              </span>
              <span className="node-caption" dir="rtl">
                יום {String(lesson.day).padStart(2, '0')}
              </span>
            </button>
          );
        })}
      </div>
      <div className="map-selected" aria-live="polite">
        <div>
          <span className="eyebrow">DAY {String(selected.day).padStart(2, '0')}</span>
          <h3 dir="auto">{selected.title}</h3>
          <span className="muted">
            <Clock3 size={13} /> עד {selected.estimatedMinutes} דקות{' '}
            {lockedIds.includes(selected.id) ? '· נפתח אחרי תרגילי פרק היסודות' : ''}
          </span>
        </div>
        <Link
          href={lockedIds.includes(selected.id) ? '/topics/CORE' : `/learn/${selected.id}`}
          className={`button ${selected.publicationStatus === 'published' ? 'primary' : 'secondary'}`}
        >
          {lockedIds.includes(selected.id)
            ? 'להשלמת פרק היסודות'
            : selected.publicationStatus === 'published'
              ? 'מעבר לשיעור'
              : 'צפייה במתווה'}
          <ArrowLeft size={16} />
        </Link>
      </div>
    </section>
  );
}

'use client';
import { useActionState, useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { Check, ArrowLeft, ArrowRight } from 'lucide-react';
import type { Assessment } from '@/lib/curriculum/assessment';
import { submitEvidence } from '@/app/assessments/actions';
import { ArtifactPicker, type SelectedArtifact } from './assessment/artifact-picker';
import { PortfolioCard } from './assessment/portfolio-card';
import { reducedMotion } from '@/lib/domain/motion';

export function AssessmentForm({
  assessment,
  submissionId,
  curriculumVersion,
  built,
}: {
  assessment: Assessment;
  submissionId: string;
  curriculumVersion: string;
  built: boolean;
}) {
  const [evidence, setEvidence] = useState<Record<string, string>>({});
  const [files, setFiles] = useState<SelectedArtifact[]>([]);
  const [index, setIndex] = useState(0),
    [included, setIncluded] = useState(false),
    [title, setTitle] = useState(assessment.title),
    [summary, setSummary] = useState(''),
    [feedback, setFeedback] = useState(''),
    [answer, setAnswer] = useState('');
  const heading = useRef<HTMLHeadingElement>(null),
    moved = useRef(false);
  const [result, action, pending] = useActionState(
    async (previous: { ok: boolean; message: string }, form: FormData) => {
      for (const item of files) form.append(`artifact:${item.criterionId}:${item.id}`, item.file);
      return submitEvidence(previous, form);
    },
    { ok: true, message: '' },
  );
  const submitted = result.ok && Boolean(result.message),
    disabled = !built || pending || submitted;
  const valid = (id: string) =>
    (evidence[id]?.trim().length || 0) >= 80 && (evidence[id]?.length || 0) <= 12000;
  const ready = assessment.criteria.filter((item) => valid(item.id)).length;
  function go(next: number) {
    moved.current = true;
    setIndex(next);
    setFeedback('');
  }
  useEffect(() => {
    if (!moved.current) return;
    heading.current?.focus({ preventScroll: true });
    heading.current?.scrollIntoView({
      block: 'start',
      behavior: reducedMotion() ? 'instant' : 'smooth',
    });
  }, [index]);
  return (
    <section className="card assessment-card" id="assessment">
      <p className="eyebrow">הוכחה מעשית · צעד אחר צעד</p>
      <h2>{assessment.title}</h2>
      <p className="muted">{assessment.instructions}</p>
      <p className="notice">
        ממלאים תשובה אחת בכל פעם. אפשר לחזור לכל שאלה. הבדיקה כאן בודקת שהמילוי הושלם; בודק מורשה
        יעריך את העבודה לאחר ההגשה.
      </p>
      {!built && (
        <p className="muted">
          השאלות זמינות לקריאה. כדי לענות ולהגיש, השלם קודם את תרגיל הבנייה וסמן אותו כהושלם בשיעור.
        </p>
      )}
      <details className="reinforcement-quiz">
        <summary>לפני שמגישים · שאלה קצרה לתרגול</summary>
        <fieldset>
          <legend>סיימת את התרגיל המעשי. מה הצעד הבא כדי להראות מה למדת?</legend>
          {[
            ['complete', 'לסמן שהגעתי לשליטה בנושא, בלי לצרף ראיות'],
            ['evidence', 'לצרף תוצאה והסבר ולהגיש אותם לבדיקה'],
            ['skip', 'לעבור הלאה בלי לבדוק מקרה בעייתי בתרגיל'],
          ].map(([value, label]) => (
            <label key={value} className="toggle-row">
              <input
                type="radio"
                name={`reinforcement-${assessment.id}`}
                value={value}
                checked={answer === value}
                onChange={() => setAnswer(value)}
              />
              {label}
            </label>
          ))}
        </fieldset>
        <p role="status">
          {answer === 'evidence'
            ? 'נכון. תוצאה והסבר מאפשרים לבודק להעריך את העבודה. ההגשה עצמה עדיין אינה אישור שליטה.'
            : answer
              ? 'נסה שוב. השלמת התרגיל היא התחלה; צריך גם להראות מה בדקת ומה הבנת.'
              : ''}
        </p>
      </details>
      <div className="assessment-progress">
        <span>
          שאלה {index + 1} מתוך {assessment.criteria.length}
        </span>
        <span>תשובות מוכנות להגשה: {ready}</span>
        <progress value={ready} max={assessment.criteria.length} aria-label="השלמת תשובות להערכה" />
      </div>
      <nav className="assessment-question-nav" aria-label="מעבר בין שאלות ההערכה">
        {assessment.criteria.map((item, i) => (
          <button
            type="button"
            key={item.id}
            aria-label={`שאלה ${i + 1}${valid(item.id) ? ' · המילוי הושלם' : ''}`}
            aria-current={i === index ? 'step' : undefined}
            onClick={() => go(i)}
            disabled={pending}
          >
            <span>{i + 1}</span>
            {valid(item.id) && <Check aria-hidden="true" size={14} />}
          </button>
        ))}
      </nav>
      <form
        action={action}
        noValidate
        onSubmit={(event) => {
          setFeedback('');
          const invalid = assessment.criteria.findIndex((item) => !valid(item.id));
          if (invalid >= 0) {
            event.preventDefault();
            go(invalid);
            setFeedback('ההגשה לא נשמרה. כתוב בין 80 ל־12,000 תווים בכל סעיף ונסה שוב.');
          }
        }}
      >
        <input type="hidden" name="submissionId" value={submissionId} />
        <input type="hidden" name="assessmentId" value={assessment.id} />
        <input type="hidden" name="rubricVersion" value={assessment.version} />
        <input type="hidden" name="curriculumVersion" value={curriculumVersion} />
        <fieldset disabled={disabled}>
          {assessment.criteria.map((item, i) => (
            <section
              className="evidence-field assessment-question"
              hidden={i !== index}
              key={item.id}
              data-mentor-kind="assessment"
              data-mentor-id={item.id}
              data-mentor-title={item.prompt}
            >
              <span className="question-type">
                {/הרצ|בדיק|תקלה|כשל/.test(item.prompt)
                  ? 'בדיקה מעשית + קבצים'
                  : 'הסבר במילים שלך + קבצים'}
              </span>
              <h3 ref={i === index ? heading : undefined} tabIndex={-1}>
                {item.prompt}
              </h3>
              <label htmlFor={item.id}>
                {i + 1}. {item.prompt}
              </label>
              <p id={`${item.id}-help`} className="muted">
                {item.evidenceHint} (80–12,000 תווים)
              </p>
              <textarea
                value={evidence[item.id] ?? ''}
                onChange={(event) =>
                  setEvidence((previous) => ({ ...previous, [item.id]: event.target.value }))
                }
                id={item.id}
                name={`evidence:${item.id}`}
                aria-describedby={`${item.id}-help ${item.id}-feedback`}
                minLength={80}
                maxLength={12000}
                rows={6}
                required
                dir="auto"
              />
              <p id={`${item.id}-feedback`} className="answer-feedback" role="status">
                {valid(item.id)
                  ? 'המילוי הושלם. איכות התשובה תיבדק לאחר ההגשה.'
                  : `עוד ${Math.max(0, 80 - (evidence[item.id]?.trim().length || 0))} תווים לפחות כדי לתאר את העבודה.`}
              </p>
              <ArtifactPicker
                criterionId={item.id}
                files={files}
                onChange={setFiles}
                disabled={disabled}
              />
            </section>
          ))}
          <div className="assessment-navigation">
            <button
              className="button secondary"
              type="button"
              disabled={index === 0}
